func writeCompletionChunk(w sseWriter, id string, created int64, modelName string, delta map[string]string, finishReason any, usage *tokenUsage, usageSource string) error {
	chunk := completionChunk{ID: id, Object: "chat.completion.chunk", Created: created, Model: modelName, Usage: usage, UsageSource: usageSource}
	chunk.Choices = append(chunk.Choices, struct {
		Index        int               `json:"index"`
		Delta        map[string]string `json:"delta"`
		FinishReason any               `json:"finish_reason"`
	}{Index: 0, Delta: delta, FinishReason: finishReason})
	data, err := json.Marshal(chunk)
	if err != nil {
		return err
	}
	return writeSSEData(w, string(data))
}

func writeSSEData(w sseWriter, data string) error {
	if _, err := fmt.Fprintf(w, "data: %s\n\n", data); err != nil {
		return err
	}
	return w.Flush()
}

func writeSSEError(w sseWriter, code, message, requestID string) error {
	payload, err := json.Marshal(map[string]any{"error": map[string]string{
		"code": code, "message": message, "type": "api_error", "request_id": requestID,
	}})
	if err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "event: error\ndata: %s\n\n", payload); err != nil {
		return err
	}
	return w.Flush()
}

func aggregateUsage(strategy, dialogue *schema.TokenUsage) (*tokenUsage, string) {
	if dialogue == nil {
		return nil, "unavailable"
	}
	usage := &tokenUsage{
		PromptTokens:     dialogue.PromptTokens,
		CompletionTokens: dialogue.CompletionTokens,
		TotalTokens:      dialogue.TotalTokens,
	}
	if strategy != nil {
		usage.PromptTokens += strategy.PromptTokens
		usage.CompletionTokens += strategy.CompletionTokens
		usage.TotalTokens += strategy.TotalTokens
	}
	return usage, "authoritative"
}

func upstreamStartError(err error) (int, string, string) {
	if errors.Is(err, context.DeadlineExceeded) {
		return consts.StatusGatewayTimeout, "upstream_timeout", "模型服务响应超时，请稍后重试"
	}
	return consts.StatusBadGateway, "upstream_error", "模型服务暂时不可用，请稍后重试"
}

